library BiggiErrorsLib {
    /* ========= Obecné ========= */
    error ZeroAddress();      // nějaký vstupní address(0)
    error ToZero();           // cílová adresa je address(0)
    error AmountZero();       // amount == 0
    error NoneAvailable();    // nic není k dispozici (claim apod.)

    /* ========= Role / přístup ========= */
    error NotDistributor();
    error NotBuybackAgent();
    error NotLiquidityManager();
    error NotPolicy();
    error NotCommunityAdmin();
    error NotAllowedCaller();

    error OnlyDripLM();       // DripDistributor: onlyDripLM
    error OnlyTreasury();     // DripDistributor: onlyTreasury

    /* ========= Konfigurace / stav ========= */
    error RewardsNotSet();
    error ReserveNotSet();
    error TreasuryNotSet();
    error TokenNotSet();

    error RouterNotSet();         // BuybackAgent: router nebo wrappedNative není nastaven
    error PolicyNotSet();         // pokud je potřeba policy a není nastavená
    error BuybacksPaused();       // policy říká, že buyback je pauznutý
    error CapExceeded();          // DripDistributor CAP (200M BIGGI) překročen
    error NotWhitelistedCollection(); // notifyMint volá ne-whitelisted kolekce
    error OnlyToken();                // funkci smí volat jen samotný BIGGI token kontrakt

    /* ========= Runtime / flow chyby ========= */
    error Cooldown();           // buyback cooldown ještě nevypršel
    error NoBiggi();            // swap proběhl, ale dorazilo 0 BIGGI
    error BadPath();            // nevalidní swap path v buyback agentovi
    error BuybackAborted();     // policy odmítla quota (consumeDailyBuybackQuota)
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./Library/BiggiErrorsLib.sol";
import "./Library/BiggiSwapLib.sol";

interface IUniswapV2Router02 {
    function WETH() external view returns (address);
    function swapExactETHForTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable returns (uint[] memory amounts);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function getAmountsOut(uint amountIn, address[] calldata path) external view returns (uint[] memory amounts);
}

interface IBiggiTreasury {
    function buybackDepositAndSplit(uint256 amount) external;
}

interface IBiggiPolicy {
    function swapSlippageBps() external view returns (uint256);
    function txDeadlineSec() external view returns (uint256);
    function minBuybackInterval() external view returns (uint256);
    function buybacksPaused() external view returns (bool);
    function maxDailyBuybackNative() external view returns (uint256);
    function consumeDailyBuybackQuota(uint256 nativeAmount) external;
}

interface IDripLM {
    function dripOnBuy(uint256 biggiBought) external;
}

contract BiggiBuybackAgent is Ownable, ReentrancyGuard {
    IERC20 public immutable BIGGI;
    IUniswapV2Router02 public router;
    address public wrappedNative;
    IBiggiTreasury public treasury;
    IBiggiPolicy   public policy;
    IDripLM        public dripLM;

    // Automation/keeper that may trigger manual buyback entrypoints (in addition to owner).
    address public keeper;

    address[] private _customPath;

    uint256 public fallbackSwapSlippageBps = 200; // 2%
    uint256 public fallbackTxDeadlineSec   = 600; // 10 min
    uint256 public fallbackMinIntervalSec  = 300; // 5 min

    uint256 public lastBuybackAt;
    uint256 public totalNativeReceived;
    uint256 public totalNativeSpent;
    uint256 public totalBiggiAcquired;

    bool public autoBuybackEnabled = true;
    bool public paused;

    event RouterSet(address router, address wrappedNative);
    event TreasurySet(address treasury);
    event PolicySet(address policy);
    event DripLMSet(address dripLM);
    event PathSet(address[] path);
    event PathCleared();
    event FallbacksSet(uint256 slipBps, uint256 deadlineSec, uint256 cooldownSec);
    event MintShareReceived(uint256 amount);
    event BuybackExecuted(uint256 nativeSpent, uint256 biggiAcquired);
    event RoutedToTreasury(uint256 amountBiggi);
    event DripNotified(address dripLM, uint256 biggiReported);
    event AutoBuybackToggled(bool enabled);
    event PausedEvent();
    event UnpausedEvent();
    event KeeperSet(address keeper);
    event RescueERC20(address token, address to, uint256 amount);
    event RescueNative(address to, uint256 amount);
    event ForwardNativeFailed(uint256 amount);

    // ponecháváme jen ty chyby, které nemáme v BiggiErrorsLib
    error RouterNotSet();
    error Cooldown();
    error NoBiggi();
    error BadPath();
    error BuybackAborted();
    error BuybacksPaused();
    error NotAuthorized();

    constructor(address biggiToken, address initialOwner) Ownable(initialOwner) {
        if (biggiToken == address(0) || initialOwner == address(0)) {
            revert BiggiErrorsLib.ZeroAddress();
        }
        BIGGI = IERC20(biggiToken);
    }

    modifier onlySelfOrOwner() {
        if (msg.sender != address(this) && msg.sender != owner()) revert NotAuthorized();
        _;
    }

    modifier onlyOwnerOrKeeper() {
        if (msg.sender != owner() && msg.sender != keeper) revert NotAuthorized();
        _;
    }

    /* ================= Admin setters (onlyOwner) ================= */
    function setRouter(address router_) external onlyOwner {
        if (router_ == address(0)) revert BiggiErrorsLib.ZeroAddress();
        router = IUniswapV2Router02(router_);
        wrappedNative = router.WETH();
        emit RouterSet(router_, wrappedNative);
        if (_customPath.length > 0) {
            if (_customPath[0] != wrappedNative || _customPath[_customPath.length - 1] != address(BIGGI)) {
                delete _customPath;
                emit PathCleared();
            }
        }
    }

    function setTreasury(address treasury_) external onlyOwner {
        if (treasury_ == address(0)) revert BiggiErrorsLib.ZeroAddress();
        treasury = IBiggiTreasury(treasury_);
        emit TreasurySet(treasury_);
    }

    function setPolicy(address policy_) external onlyOwner {
        // může být i address(0) = bez policy, proto nekontrolujeme ZeroAddress
        policy = IBiggiPolicy(policy_);
        emit PolicySet(policy_);
    }

    function setDripLM(address dripLM_) external onlyOwner {
        // dripLM může být vypnutý (address(0)), proto nekontrolujeme ZeroAddress
        dripLM = IDripLM(dripLM_);
        emit DripLMSet(dripLM_);
    }

    function setKeeper(address keeper_) external onlyOwner {
        keeper = keeper_;
        emit KeeperSet(keeper_);
    }

    function setSwapPath(address[] calldata newPath) external onlyOwner {
        if (address(router) == address(0)) revert RouterNotSet();
        if (newPath.length < 2 || newPath.length > 5) revert BadPath();
        if (newPath[0] != wrappedNative) revert BadPath();
        if (newPath[newPath.length - 1] != address(BIGGI)) revert BadPath();
        delete _customPath;
        for (uint i = 0; i < newPath.length; ++i) _customPath.push(newPath[i]);
        emit PathSet(newPath);
    }

    function clearSwapPath() external onlyOwner {
        if (_customPath.length > 0) {
            delete _customPath;
            emit PathCleared();
        }
    }

    function setFallbacks(uint256 slipBps, uint256 deadlineSec, uint256 cooldownSec) external onlyOwner {
        require(slipBps <= 10_000, "BPS_HIGH");
        require(deadlineSec > 0 && deadlineSec <= 1 days, "DEADLINE_BAD");
        require(cooldownSec <= 1 days, "COOLDOWN_BAD");
        fallbackSwapSlippageBps = slipBps;
        fallbackTxDeadlineSec   = deadlineSec;
        fallbackMinIntervalSec  = cooldownSec;
        emit FallbacksSet(slipBps, deadlineSec, cooldownSec);
    }

    function toggleAutoBuyback(bool enabled) external onlyOwner {
        autoBuybackEnabled = enabled;
        emit AutoBuybackToggled(enabled);
    }

    function pause() external onlyOwner { paused = true; emit PausedEvent(); }
    function unpause() external onlyOwner { paused = false; emit UnpausedEvent(); }

    /* ================= Core: receiving share & auto buyback ================= */
    // Distributor -> this function payable
    function receiveMintShare() external payable {
        if (msg.value == 0) revert BiggiErrorsLib.AmountZero();
        totalNativeReceived += msg.value;
        emit MintShareReceived(msg.value);

        if (paused) return;

        if (autoBuybackEnabled) {
            if (address(treasury) == address(0)) revert BiggiErrorsLib.TreasuryNotSet();
            if (address(router) == address(0) || wrappedNative == address(0)) revert RouterNotSet();
            // try internal flow; if it reverts, fallback to forwarding native to treasury
            try this._autoBuyback{value: msg.value}() {
                // success
            } catch {
                _forwardNativeToTreasury(msg.value);
            }
        } else {
            // keep native here for manual buyback
        }
    }

    receive() external payable {}

    // perform buyback using sent native (must be called via this contract so msg.sender == address(this))
    function _autoBuyback() external payable nonReentrant {
        require(msg.sender == address(this), "internal only");
        uint256 nativeAmt = msg.value;
        _guardsAndQuota(nativeAmt);

        uint256 acquired = 0;
        bool swapped = false;
        try this._swapNativeForBiggi{value: nativeAmt}(nativeAmt, 0) returns (uint256 got) {
            acquired = got;
            swapped = true;
        } catch {
            swapped = false;
        }

        if (!swapped) {
            _forwardNativeToTreasury(nativeAmt);
            return;
        }

        if (acquired == 0) {
            _forwardNativeToTreasury(nativeAmt);
            return;
        }

        // ==> VARIANTA A: approve treasury (so treasury can pull tokens) THEN call buybackDepositAndSplit
        _approveTokenForTreasury(acquired);

        try treasury.buybackDepositAndSplit(acquired) {
            emit RoutedToTreasury(acquired);
        } catch {
            // if treasury fails, forward native instead
            _forwardNativeToTreasury(nativeAmt);
            return;
        }

        lastBuybackAt = block.timestamp;
        totalNativeSpent += nativeAmt;
        totalBiggiAcquired += acquired;
        emit BuybackExecuted(nativeAmt, acquired);

        if (address(dripLM) != address(0)) {
            try dripLM.dripOnBuy(acquired) {
                emit DripNotified(address(dripLM), acquired);
            } catch {
                // ignore drip failure
            }
        }
    }

    /* ================= internal helpers ================= */
    function _guardsAndQuota(uint256 nativeAmount) internal {
        if (address(router) == address(0) || wrappedNative == address(0)) revert RouterNotSet();
        if (address(treasury) == address(0)) revert BiggiErrorsLib.TreasuryNotSet();
        if (address(policy) != address(0)) {
            if (policy.buybacksPaused()) revert BuybacksPaused();
            uint256 interval = policy.minBuybackInterval();
            if (interval == 0) interval = fallbackMinIntervalSec;
            if (lastBuybackAt != 0 && block.timestamp < lastBuybackAt + interval) revert Cooldown();
            uint256 maxDaily = policy.maxDailyBuybackNative();
            if (maxDaily > 0 && nativeAmount > maxDaily) revert BuybackAborted();

            // enforce daily quota via policy (uses nativeAmount) - wrapped in try/catch to preserve safety
            try policy.consumeDailyBuybackQuota(nativeAmount) {
            } catch {
                revert BuybackAborted();
            }
        } else {
            uint256 interval = fallbackMinIntervalSec;
            if (lastBuybackAt != 0 && block.timestamp < lastBuybackAt + interval) revert Cooldown();
        }
    }

    function _path() internal view returns (address[] memory p) {
        if (_customPath.length > 0) {
            p = new address[](_customPath.length);
            for (uint i = 0; i < _customPath.length; ++i) p[i] = _customPath[i];
        } else {
            p = new address[](2);
            p[0] = wrappedNative;
            p[1] = address(BIGGI);
        }
    }

    // swap native -> BIGGI, returns acquired amount (external, no nonReentrant; guarded by caller)
    function _swapNativeForBiggi(uint256 nativeAmt, uint256 minOut) external payable onlySelfOrOwner returns (uint256 acquired) {
        address[] memory path = _path();

        uint256 pre = BIGGI.balanceOf(address(this));

        uint256 deadline = block.timestamp + fallbackTxDeadlineSec;
        if (address(policy) != address(0)) {
            try policy.txDeadlineSec() returns (uint256 d) {
                deadline = block.timestamp + d;
            } catch {}
        }

        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: nativeAmt}(
            minOut,
            path,
            address(this),
            deadline
        );

        uint256 post = BIGGI.balanceOf(address(this));
        acquired = post - pre;
        if (acquired == 0) revert NoBiggi();
    }

    // approve treasury safely (0 -> amount pattern)
    function _approveTokenForTreasury(uint256 amount) internal {
        // first try to set allowance to 0
        (bool ok0, bytes memory d0) = address(BIGGI).call(
            abi.encodeWithSelector(IERC20.approve.selector, address(treasury), 0)
        );
        require(ok0 && (d0.length == 0 || abi.decode(d0, (bool))), "approve0 failed");

        (bool ok1, bytes memory d1) = address(BIGGI).call(
            abi.encodeWithSelector(IERC20.approve.selector, address(treasury), amount)
        );
        require(ok1 && (d1.length == 0 || abi.decode(d1, (bool))), "approve failed");
    }

    function _forwardNativeToTreasury(uint256 amount) internal {
        if (address(treasury) == address(0)) revert BiggiErrorsLib.TreasuryNotSet();
        (bool ok, ) = payable(address(treasury)).call{value: amount}("");
        if (!ok) {
            emit ForwardNativeFailed(amount);
        }
    }

    /* ================= manual buyback (owner) ================= */
    function buybackAllToTreasury(uint256 minOut) external onlyOwnerOrKeeper nonReentrant {
        uint256 bal = address(this).balance;
        require(bal > 0, "no native");
        _guardsAndQuota(bal);

        uint256 acquired = 0;
        bool swapped = false;
        try this._swapNativeForBiggi{value: bal}(bal, minOut) returns (uint256 got) {
            acquired = got;
            swapped = true;
        } catch {
            swapped = false;
        }

        if (!swapped) {
            _forwardNativeToTreasury(bal);
            return;
        }

        _approveTokenForTreasury(acquired);

        try treasury.buybackDepositAndSplit(acquired) {
            emit RoutedToTreasury(acquired);
        } catch {
            _forwardNativeToTreasury(bal);
            return;
        }

        lastBuybackAt = block.timestamp;
        totalNativeSpent += bal;
        totalBiggiAcquired += acquired;
        emit BuybackExecuted(bal, acquired);

        if (address(dripLM) != address(0)) {
            try dripLM.dripOnBuy(acquired) {
                emit DripNotified(address(dripLM), acquired);
            } catch {}
        }
    }

    function buybackAmountToTreasury(uint256 nativeAmount, uint256 minOut) external onlyOwnerOrKeeper nonReentrant {
        require(nativeAmount > 0 && address(this).balance >= nativeAmount, "bad amount");
        _guardsAndQuota(nativeAmount);

        uint256 acquired = 0;
        bool swapped = false;
        try this._swapNativeForBiggi{value: nativeAmount}(nativeAmount, minOut) returns (uint256 got) {
            acquired = got;
            swapped = true;
        } catch {
            swapped = false;
        }

        if (!swapped) {
            _forwardNativeToTreasury(nativeAmount);
            return;
        }

        _approveTokenForTreasury(acquired);

        try treasury.buybackDepositAndSplit(acquired) {
            emit RoutedToTreasury(acquired);
        } catch {
            _forwardNativeToTreasury(nativeAmount);
            return;
        }

        lastBuybackAt = block.timestamp;
        totalNativeSpent += nativeAmount;
        totalBiggiAcquired += acquired;
        emit BuybackExecuted(nativeAmount, acquired);

        if (address(dripLM) != address(0)) {
            try dripLM.dripOnBuy(acquired) {
                emit DripNotified(address(dripLM), acquired);
            } catch {}
        }
    }

    /* ================= rescue ================= */
    function rescueERC20(address token, address to, uint256 amount) external onlyOwner {
        IERC20(token).transfer(to, amount);
        emit RescueERC20(token, to, amount);
    }

    function rescueNative(address payable to, uint256 amount) external onlyOwner {
        to.transfer(amount);
        emit RescueNative(address(to), amount);
    }

    /* ================= view helpers ================= */
    function pathCustom() external view returns (address[] memory) { return _customPath; }
    function nativeBalance() external view returns (uint256) { return address(this).balance; }
    function biggiBalance() external view returns (uint256) { return BIGGI.balanceOf(address(this)); }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

import "./Library/BiggiErrorsLib.sol";
import "./Library/BiggiCapsLib.sol";

/// @notice Účetní kontrakt držící BIGGI pro DripLM.
/// - CAP nezávislý na treasury (DRIP_DISTRIBUTOR_CAP)
/// - whitelist kolekcí pro notifyMint (accounting)
contract BiggiDripDistributor is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    IERC20 public immutable BIGGI;

    address public dripLM;
    address public treasury;

    // volitelný operator (např. DripLM), který může dynamicky přepisovat tokensPerMint
    address public tokensPerMintOperator;

    // kolik BIGGI (raw) se účetně alokuje za 1 mint
    uint256 public tokensPerMint;

    // účetní stav (claimovatelné)
    uint256 public availableTokens;

    // kumulativní statistiky
    uint256 public totalReceived;
    uint256 public totalClaimed;
    uint256 public totalNotified;
    bool public historicalStateSeeded;

    uint256 public constant CAP = BiggiCapsLib.DRIP_DISTRIBUTOR_TOTAL_CAP;

    mapping(address => bool) public collections;

    /* ===== events ===== */
    event CollectionSet(address indexed coll, bool allowed);
    event DripLMSet(address indexed oldLM, address indexed newLM);
    event TreasurySet(address indexed oldT, address indexed newT);
    event TokensPerMintOperatorSet(address indexed oldOp, address indexed newOp);
    event TokensPerMintSet(uint256 oldVal, uint256 newVal);

    event NotifyMint(address indexed coll, uint256 count, uint256 tokensAdded);
    event Claimed(address indexed to, uint256 amount);

    event TopUp(address indexed from, uint256 amount);
    event NotifyTokenMint(address indexed tokenContract, uint256 amount);
    event HistoricalStateSeeded(
        uint256 totalReceived,
        uint256 totalClaimed,
        uint256 totalNotified,
        uint256 availableTokens
    );

    event RescueERC20(address token, address to, uint256 amount);
    event RescueNative(address to, uint256 amount);

    modifier onlyDripLM() {
        if (msg.sender != dripLM) revert BiggiErrorsLib.OnlyDripLM();
        _;
    }

    modifier onlyTreasury() {
        if (msg.sender != treasury) revert BiggiErrorsLib.OnlyTreasury();
        _;
    }

    constructor(address token_, address initialOwner) Ownable(initialOwner) {
        if (token_ == address(0) || initialOwner == address(0)) {
            revert BiggiErrorsLib.ZeroAddress();
        }
        BIGGI = IERC20(token_);
    }

    /* ===== admin setters ===== */

    function syncAvailableToBalance() external onlyOwner whenNotPaused {
        uint256 bal = BIGGI.balanceOf(address(this));
        availableTokens = bal;
    }

    function setCollection(address coll, bool allowed) external onlyOwner {
        if (coll == address(0)) revert BiggiErrorsLib.ZeroAddress();
        collections[coll] = allowed;
        emit CollectionSet(coll, allowed);
    }

    function setDripLM(address lm) external onlyOwner {
        if (lm == address(0)) revert BiggiErrorsLib.ZeroAddress();
        emit DripLMSet(dripLM, lm);
        dripLM = lm;
    }

    function setTreasury(address t) external onlyOwner {
        if (t == address(0)) revert BiggiErrorsLib.ZeroAddress();
        emit TreasurySet(treasury, t);
        treasury = t;
    }

    function setTokensPerMintOperator(address op) external onlyOwner {
        emit TokensPerMintOperatorSet(tokensPerMintOperator, op);
        tokensPerMintOperator = op;
    }

    /// @notice Owner nastaví tokensPerMint v raw jednotkách (např. 1000 * 1e18)
    function setTokensPerMint(uint256 v) external onlyOwner {
        emit TokensPerMintSet(tokensPerMint, v);
        tokensPerMint = v;
    }

    /// @notice Operator (např. DripLM) může dynamicky přepsat tokensPerMint podle buybacku
    function setTokensPerMintFromOperator(uint256 v) external {
        require(msg.sender == tokensPerMintOperator, "not operator");
        emit TokensPerMintSet(tokensPerMint, v);
        tokensPerMint = v;
    }

    function seedHistoricalState(
        uint256 totalReceived_,
        uint256 totalClaimed_,
        uint256 totalNotified_,
        uint256 availableTokens_
    ) external onlyOwner {
        require(!historicalStateSeeded, "already seeded");
        totalReceived = totalReceived_;
        totalClaimed = totalClaimed_;
        totalNotified = totalNotified_;
        availableTokens = availableTokens_;
        historicalStateSeeded = true;
        emit HistoricalStateSeeded(totalReceived_, totalClaimed_, totalNotified_, availableTokens_);
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    /* ===== notify from collection (accounting only) ===== */
    function notifyMint(uint256 mintedCount) external nonReentrant whenNotPaused {
        if (mintedCount == 0) revert BiggiErrorsLib.AmountZero();
        if (!collections[msg.sender]) revert BiggiErrorsLib.NotWhitelistedCollection();

        uint256 add = tokensPerMint * mintedCount;
        availableTokens += add;
        totalNotified += add;

        emit NotifyMint(msg.sender, mintedCount, add);
    }

    /* ===== token contract notification (initial/top-up) ===== */
    function notifyTokenMint(uint256 amount) external nonReentrant whenNotPaused {
        if (amount == 0) revert BiggiErrorsLib.AmountZero();
        if (msg.sender != address(BIGGI)) revert BiggiErrorsLib.OnlyToken();
        if (totalReceived + amount > CAP) revert BiggiErrorsLib.CapExceeded();

        uint256 netHeld = totalReceived >= totalClaimed ? (totalReceived - totalClaimed) : 0;
        uint256 bal = BIGGI.balanceOf(address(this));
        require(bal >= netHeld + amount, "token not transferred");

        totalReceived += amount;
        availableTokens += amount;

        emit NotifyTokenMint(msg.sender, amount);
        emit TopUp(msg.sender, amount);
    }

    /* ===== treasury deposit (TopUp) ===== */
    function depositTokens(uint256 amount) external nonReentrant whenNotPaused onlyTreasury {
        if (amount == 0) revert BiggiErrorsLib.AmountZero();

        BIGGI.safeTransferFrom(msg.sender, address(this), amount);

        totalReceived += amount;
        availableTokens += amount;

        emit TopUp(msg.sender, amount);
    }
    // supply-controller top-ups are routed through BIGGI.notifyTokenMint(amount)

    /* ===== claim by DripLM ===== */
    function claim(uint256 amountRequested) external nonReentrant onlyDripLM whenNotPaused {
        if (amountRequested == 0) revert BiggiErrorsLib.AmountZero();

        uint256 bal = BIGGI.balanceOf(address(this));
        uint256 toSend = amountRequested;

        if (toSend > availableTokens) toSend = availableTokens;
        if (toSend > bal) toSend = bal;

        if (toSend == 0) revert BiggiErrorsLib.NoneAvailable();

        availableTokens -= toSend;
        totalClaimed += toSend;

        BIGGI.safeTransfer(msg.sender, toSend);
        emit Claimed(msg.sender, toSend);
    }

    function claimTo(address to, uint256 amountRequested) external nonReentrant onlyDripLM whenNotPaused {
        if (to == address(0)) revert BiggiErrorsLib.ToZero();
        if (amountRequested == 0) revert BiggiErrorsLib.AmountZero();

        uint256 bal = BIGGI.balanceOf(address(this));
        uint256 toSend = amountRequested;

        if (toSend > availableTokens) toSend = availableTokens;
        if (toSend > bal) toSend = bal;

        if (toSend == 0) revert BiggiErrorsLib.NoneAvailable();

        availableTokens -= toSend;
        totalClaimed += toSend;

        BIGGI.safeTransfer(to, toSend);
        emit Claimed(to, toSend);
    }

    /* ===== rescue & helpers ===== */
    function rescueERC20(address token, address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert BiggiErrorsLib.ToZero();
        IERC20(token).safeTransfer(to, amount);
        emit RescueERC20(token, to, amount);
    }

    function rescueNative(address payable to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert BiggiErrorsLib.ToZero();
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "native xfer fail");
        emit RescueNative(address(to), amount);
    }

    receive() external payable {}

    /* ===== view helpers ===== */

    function biggiBalance() public view returns (uint256) {
        return BIGGI.balanceOf(address(this));
    }

    function effectiveAvailable() public view returns (uint256) {
        uint256 bal = BIGGI.balanceOf(address(this));
        return availableTokens <= bal ? availableTokens : bal;
    }

    function getAvailable() external view returns (uint256) { return availableTokens; }
    function getTotalNotified() external view returns (uint256) { return totalNotified; }
    function getTotalClaimed() external view returns (uint256) { return totalClaimed; }
    function getTotalReceived() external view returns (uint256) { return totalReceived; }
    function isCollection(address a) external view returns (bool) { return collections[a]; }

    function capRemaining() external view returns (uint256) {
        if (totalReceived >= CAP) return 0;
        return CAP - totalReceived;
    }

    struct Snapshot {
        address token;
        address dripLM;
        address treasury;
        address operator;
        uint256 tokensPerMint;
        uint256 available;
        uint256 effectiveAvailable;
        uint256 totalReceived;
        uint256 totalClaimed;
        uint256 totalNotified;
        uint256 cap;
        uint256 capRemaining;
        uint256 balance;
        bool paused;
    }

    function snapshot() external view returns (Snapshot memory s) {
        s.token = address(BIGGI);
        s.dripLM = dripLM;
        s.treasury = treasury;
        s.operator = tokensPerMintOperator;
        s.tokensPerMint = tokensPerMint;

        s.available = availableTokens;

        uint256 bal = BIGGI.balanceOf(address(this));
        s.balance = bal;
        s.effectiveAvailable = availableTokens <= bal ? availableTokens : bal;

        s.totalReceived = totalReceived;
        s.totalClaimed = totalClaimed;
        s.totalNotified = totalNotified;

        s.cap = CAP;
        s.capRemaining = totalReceived >= CAP ? 0 : (CAP - totalReceived);
        s.paused = paused();
    }
}

